# Code generated by Claude
# Regenerates the reference baselines of the control-loop bench scenarios (experiments/baselines/<scenario>_reference.csv) after the robot model changed (the neck was removed, M153).
# usage: bash experiments/cc_bench_regen.sh [LOGTAG]      (run it in a detached tmux session; one MuJoCo process at a time)
# For each scenario (manual, teleop, policy): run it twice headless (CC_HEADLESS=1) into data/cc_baseline/regen/<scenario>_1.csv and _2.csv; the two must be byte-identical
# (the scenarios are deterministic); only then the result is copied to a temporary file next to the reference and renamed over it (an interrupted run leaves the old reference).
cd "$(dirname "$0")/.."
export CC_HEADLESS=1
OUT=data/cc_baseline/regen
mkdir -p $OUT
for sc in manual teleop policy; do
  for n in 1 2; do
    echo "=== $sc run $n start $(date +%T), free memory $(free -m | awk 'NR==2{print $7}') MB available"
    bash experiments/cc_bench_scenarios.sh $sc $OUT/${sc}_$n.csv > $OUT/${sc}_$n.out 2>&1 || { echo "FAILED $sc run $n"; exit 1; }
  done
  if cmp -s $OUT/${sc}_1.csv $OUT/${sc}_2.csv && [ -s $OUT/${sc}_1.csv ]; then
    cp $OUT/${sc}_1.csv experiments/baselines/${sc}_reference.csv.tmp && mv experiments/baselines/${sc}_reference.csv.tmp experiments/baselines/${sc}_reference.csv
    echo "=== $sc: the two runs are byte-identical ($(wc -l < $OUT/${sc}_1.csv) rows); reference replaced"
  else
    echo "=== $sc: the two runs DIFFER or are empty: reference NOT replaced"
  fi
done
echo REGEN_DONE
